INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish6', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":12,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Æble, pære og banan hører sammen. Hvilket fælles ord passer på dem?","o":["frugt","grøntsager","slik","drikkevarer"],"a":"frugt","r":"Æbler, pærer og bananer er søde og vokser på træer og planter. Den slags kalder man frugt."},
{"l":31,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det regner i dag. Yusuf tager sine gummistøvler på.' Hvorfor tager Yusuf gummistøvler på?","o":["Fordi det sner","Fordi det regner","Fordi solen skinner","Fordi det er varmt"],"a":"Fordi det regner","r":"Teksten starter med, at det regner. Derfor skal Yusuf have støvler på, som kan tåle vand."},
{"l":49,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Freja fylder ni år i dag. Hun får en cykel af sin mor og far.' Hvad får Freja af sine forældre?","o":["En bold","En bog","En cykel","En kat"],"a":"En cykel","r":"Den anden sætning fortæller, at hun får en cykel af sin mor og far."},
{"l":72,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken farve har et modent jordbær? Vælg den rigtige stavemåde.","o":["rødd","røj","røe","rød"],"a":"rød","r":"Farven ender på blødt d, og det skrives med ét d."},
{"l":92,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Liam har glemt sin madpakke. Klokken er tolv, og hans mave rumler.' Hvordan har Liam det?","o":["Han er sulten","Han er bange","Han er træt","Han er vred"],"a":"Han er sulten","r":"Maven rumler, når man trænger til mad, og Liam har ingen madpakke med."},
{"l":109,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I haven står et stort æbletræ. Om efteråret plukker vi æbler og laver most.' Hvornår plukker de æbler?","o":["Om foråret","Om efteråret","Om vinteren","Om sommeren"],"a":"Om efteråret","r":"Der står 'om efteråret' i den anden sætning, og det er den tid, æblerne er modne."},
{"l":132,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om bussen skal slutte med spørgsmålstegn?","o":["Bussen kommer nu","Vi venter på bussen","Hvornår kommer bussen","Bussen er gul"],"a":"Hvornår kommer bussen","r":"'Hvornår' er et spørgeord, så her spørger man om noget. De andre sætninger fortæller bare noget."},
{"l":153,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mads står på vippen og kigger ned. Hans ben ryster. Han tør ikke hoppe i vandet.' Hvordan har Mads det?","o":["Han keder sig","Han er vred","Han er sulten","Han er bange"],"a":"Han er bange","r":"Rystende ben og ordene 'tør ikke' viser, at Mads er bange."},
{"l":170,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ali har fået en ny tegneserie. Han læser den i sengen. Han griner højt af den sjove hund.' Hvad er sjovt i tegneserien?","o":["Hunden","Sengen","Ali","Læreren"],"a":"Hunden","r":"Der står, at Ali griner af den sjove hund. Det er altså hunden, der er sjov."},
{"l":189,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Noget, I synger i musiktimen. Hvordan staves det?","o":["sangg","sang","sanng","sangk"],"a":"sang","r":"Ordet ender på ng. Den lyd skrives altid med ét n og ét g her."},
{"l":213,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Theo tager sin hue, sine vanter og sit halstørklæde på. Udenfor er alt hvidt.' Hvilken årstid er det nok?","o":["Sommer","Forår","Vinter","Efterår"],"a":"Vinter","r":"Tøjet er varmt, og alt er hvidt af sne. Det passer på vinteren."},
{"l":231,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bien flyver fra blomst til blomst. Den henter nektar. Af nektar laver bierne honning.' Hvad laver bierne af nektar?","o":["Blomster","Voks","Vand","Honning"],"a":"Honning","r":"Den sidste sætning fortæller, at bierne laver honning af nektar."},
{"l":252,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en, der snorker?","o":["trækker vejret højt, mens man sover","siger mærkelige ord, mens man sover","går rundt i huset, mens man sover","sparker til dynen, mens man sover"],"a":"trækker vejret højt, mens man sover","r":"Når man snorker, laver næsen og halsen en rumlende lyd, mens man sover."},
{"l":272,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Der står mange træer tæt, og man kan finde svampe der. Hvilket ord er stavet rigtigt?","o":["skou","skov","skow","skovv"],"a":"skov","r":"Lyden til sidst skrives med ét v, selvom den kan lyde som u."},
{"l":291,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Elias går til fodbold om mandagen. Hans søster Layla går til dans om onsdagen. Om fredagen spiser de pizza alle sammen.' Hvad sker der om fredagen?","o":["Layla går til dans","Elias spiller fodbold","Familien spiser pizza","Familien går i biografen"],"a":"Familien spiser pizza","r":"Sidste sætning siger, at de spiser pizza om fredagen. Fodbold er mandag, og dans er onsdag."},
{"l":312,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'starte'?","o":["stoppe","vente","glemme","begynde"],"a":"begynde","r":"At starte og at begynde betyder det samme. Timen kan starte eller begynde klokken otte."},
{"l":331,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den lyser på himlen om natten og kan se ud som en banan. Vælg den rigtige stavemåde.","o":["måne","månne","mone","måene"],"a":"måne","r":"Vokalen er lang, så der skal kun ét n. Ordet skrives med å."},
{"l":349,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'gratis'?","o":["at det koster meget lidt","at det ikke koster noget","at det er sat ned i pris","at man skal betale bagefter"],"a":"at det ikke koster noget","r":"Er noget gratis, får man det uden at betale. Noget billigt koster stadig lidt."},
{"l":372,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde for det modsatte af varm.","o":["koll","kolt","kold","kåld"],"a":"kold","r":"Ordet ender på stumt d efter l, ligesom 'guld'. Det lyder med å, men skrives med o."},
{"l":390,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem har skrevet eventyret 'Prinsessen på ærten'?","o":["Astrid Lindgren","Brødrene Grimm","Ole Lund Kirkegaard","H.C. Andersen"],"a":"H.C. Andersen","r":"H.C. Andersen er Danmarks mest kendte eventyrforfatter. Han har også skrevet 'Fyrtøjet' og 'Tommelise'."},
{"l":409,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Gaffel, kniv og ske ligger i skuffen. Hvad kalder man dem med ét ord?","o":["bestik","legetøj","værktøj","service"],"a":"bestik","r":"Det, man spiser med, kalder man bestik. Tallerkener og kopper hedder service."},
{"l":431,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du går på det indenfor, og tæppet ligger på det. Hvilken stavemåde er rigtig?","o":["gull","gulv","gulf","gullv"],"a":"gulv","r":"Ordet ender på lv med stumt v. Uden v'et ville det være farven 'gul'."},
{"l":448,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Fem ___ bar sofaen ind i huset.'","o":["mand","manden","mænd","mændene"],"a":"mænd","r":"'Mand' ændrer sig i flertal, så a bliver til æ: en mand, fem mænd."},
{"l":469,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en havn?","o":["et sted, hvor fly lander","et sted, hvor tog holder","et sted, hvor busser holder","et sted, hvor skibe lægger til"],"a":"et sted, hvor skibe lægger til","r":"I en havn kan skibe ligge i læ og få læsset varer af og på. Fly lander i en lufthavn."},
{"l":491,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Signe glemte sin paraply i bussen. Da hun kom hjem, var hendes hår dryppende vådt.' Hvordan var vejret nok?","o":["Det regnede","Solen skinnede","Det var tørt og stille","Det var tåget"],"a":"Det regnede","r":"Hun manglede paraplyen og kom hjem med vådt hår. Så må det have regnet."},
{"l":513,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken slags ord er 'Mille', når det er navnet på en pige?","o":["fællesnavn","egennavn","udsagnsord","tillægsord"],"a":"egennavn","r":"Et egennavn er det navn, der hører til én bestemt person, by eller ting. 'Pige' er derimod et fællesnavn."},
{"l":530,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Jeg løb hen til søen, men jeg kunne ikke se min hund.' Hvilket ord viser, at den, der fortæller, selv er med i historien?","o":["søen","hund","jeg","løb"],"a":"jeg","r":"Når der står 'jeg', er fortælleren selv med i historien. Det kaldes en jeg-fortæller."},
{"l":551,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bo har fået en lillesøster. Hun sover det meste af dagen. Når hun er vågen, græder hun tit.' Hvad gør lillesøsteren mest?","o":["Hun leger","Hun spiser","Hun græder","Hun sover"],"a":"Hun sover","r":"Der står, at hun sover det meste af dagen. Hun græder kun tit, når hun er vågen."},
{"l":569,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sebastian har cyklet langt. Nu sidder han på en bænk og drikker hele sin vandflaske tom. Hans trøje er våd af sved.' Hvordan har Sebastian det?","o":["Han er varm og tørstig","Han fryser","Han er sulten og vred","Han er søvnig og kold"],"a":"Han er varm og tørstig","r":"Han sveder og drikker en hel flaske. Det viser, at han er varm og tørstig."},
{"l":589,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Til en fødselsdag plejer vi at ___ for barnet.'","o":["syngge","synge","sønge","synnge"],"a":"synge","r":"Ordet skrives med y og ng. Der skal ikke dobbelt g eller dobbelt n."},
{"l":612,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort bogstav: 'I juli rejser vi til norge.'?","o":["juli","rejser","norge","til"],"a":"norge","r":"Norge er navnet på et land. Måneder som juli skrives med lille på dansk."},
{"l":630,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt tillægsordet i den rigtige form: 'Der står et ___ bord i klassen.'","o":["lang","lange","længst","langt"],"a":"langt","r":"Det hedder et bord, så tillægsordet skal have -t: et langt bord."},
{"l":649,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør to, der skændes?","o":["taler vredt til hinanden","hvisker stille til hinanden","laver sjov med hinanden","løber om kap med hinanden"],"a":"taler vredt til hinanden","r":"Når man skændes, er man uvenner og siger vrede ting til hinanden."},
{"l":670,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken bog er faglitteratur?","o":["Et eventyr om en talende bi","En bog om, hvordan bier laver honning","En historie om en bi, der flyver til månen","En rimhistorie om en bi, der går i skole"],"a":"En bog om, hvordan bier laver honning","r":"Faglitteratur fortæller om virkeligheden og giver os viden. De andre bøger er opdigtede historier."},
{"l":689,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet, hvor du går hver dag for at lære noget. Vælg den rigtige stavemåde.","o":["skolle","skoole","skole","scole"],"a":"skole","r":"O'et er langt, så der skal kun ét l."},
{"l":708,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Min fødselsdag er i maj, og clara kommer til fest.'?","o":["fødselsdag","maj","fest","clara"],"a":"clara","r":"Clara er et navn. Måneder som maj skrives med lille."},
{"l":732,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Der mangler ét komma i: 'Ida løb hoppede og dansede.' Hvilket ord skal kommaet stå efter?","o":["løb","hoppede","og","dansede"],"a":"løb","r":"Ida gør tre ting, og man opremser dem med komma. Mellem 'hoppede' og 'dansede' står 'og', så der skal ikke komma."},
{"l":747,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Pausen, hvor eleverne løber ud i skolegården. Hvilket ord er stavet rigtigt?","o":["frikvater","frikvarter","frikvartær","frikvarteer"],"a":"frikvarter","r":"Ordet består af 'fri' og 'kvarter'. Husk r'et foran t."},
{"l":769,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man en person, der skriver bøger?","o":["en skuespiller","en bibliotekar","en forfatter","en maler"],"a":"en forfatter","r":"En forfatter finder på og skriver bøger. En bibliotekar arbejder med at låne bøgerne ud."},
{"l":789,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Årets første måned. Find den rigtige stavemåde.","o":["janaur","januaer","jannuar","januar"],"a":"januar","r":"Der er ét n, og ordet slutter på -uar ligesom 'februar'."},
{"l":810,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken slags tekst viser, hvad du skal bruge, og hvordan du bager boller?","o":["en opskrift","en madplan","et digt","en indkøbsliste"],"a":"en opskrift","r":"En opskrift viser først, hvad du skal bruge. Bagefter står der trin for trin, hvad du skal gøre."},
{"l":829,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'fej'?","o":["stærk","modig","venlig","doven"],"a":"modig","r":"Den, der er fej, tør ikke stå ved noget. Den, der er modig, tør godt, selv om det er svært."},
{"l":851,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige stedord: 'Han kørte ___ hjem efter træningen.'","o":["vi","I","os","de"],"a":"os","r":"Det er ham, der kører, og os, der bliver kørt. Så hedder det 'os' og ikke 'vi'."},
{"l":872,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hele familien sad på tæpper i haven. Der var kage og saft, og far spillede guitar. Mormor sagde, at det var den bedste dag i hele sommeren.' Hvilken overskrift passer bedst?","o":["En dårlig dag for mormor","Far lærer at spille guitar","Da kagen blev væk","En hyggelig dag i haven"],"a":"En hyggelig dag i haven","r":"Teksten handler om familien, der hygger sig i haven. De andre overskrifter passer ikke til hele teksten."},
{"l":889,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Vi ___ en film i aften.'","o":["ser","se","seer","cer"],"a":"ser","r":"I nutid kommer der bare et r på. Ordet har kun ét e. En 'seer' er en person, der kigger på noget."},
{"l":907,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mikael bor på en ø. Når han skal til fodbold, sejler han med færgen. Hvis det stormer meget, sejler færgen ikke, og så må han blive hjemme.' Hvorfor kan Mikael ikke altid komme til fodbold?","o":["Hans mor vil ikke køre ham","Færgen sejler ikke i storm","Træneren er ofte syg","Han har glemt sine støvler"],"a":"Færgen sejler ikke i storm","r":"Den sidste sætning forklarer det: I storm sejler færgen ikke, og så kan han ikke komme væk fra øen."},
{"l":929,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Blåhvalen er det ___ dyr i verden.'","o":["større","størst","største","stort"],"a":"største","r":"Intet dyr er større, så det skal være højeste grad. Efter 'det' får ordet et -e: det største dyr."},
{"l":949,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en ørken?","o":["et vådt område med høje træer","et højt område med sne på toppen","et område med mange små søer","et tørt område med meget lidt regn"],"a":"et tørt område med meget lidt regn","r":"I en ørken regner det næsten aldrig, og derfor vokser der kun få planter."},
{"l":968,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er højeste grad af tillægsordet her: 'ung – yngre – ___'?","o":["yngst","unge","ungt","ung"],"a":"yngst","r":"Højeste grad er den sidste i rækken. Den, der er yngre end alle andre, er yngst."},
{"l":989,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Min bror kan lide is, og det kan jeg ___.'","o":["åså","også","ågså","osse"],"a":"også","r":"Ordet begynder med o og slutter på å. G'et er stumt, men det skal med."},
{"l":1009,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hund, hval og mus giver deres unger mælk. Hvilken dyregruppe hører de til?","o":["fugle","fisk","pattedyr","insekter"],"a":"pattedyr","r":"Pattedyr giver mælk til deres unger. Selv om hvalen lever i havet, er den ikke en fisk."},
{"l":1028,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kaja stod med sit skolefoto i hånden. Hun havde lukket begge øjne, lige da der blev taget billede. Hun lagde det langsomt ned i bunden af tasken.' Hvad synes Kaja om billedet?","o":["Hun er glad for det","Hun vil give det til mor","Hun synes, det er sjovt","Hun synes, det er pinligt"],"a":"Hun synes, det er pinligt","r":"Hun har lukkede øjne på billedet og gemmer det i bunden af tasken. Så vil hun ikke vise det frem."},
{"l":1047,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'slå to fluer med ét smæk'?","o":["at klare to ting på én gang","at gøre noget dobbelt så langsomt","at vælge den ene af to ting","at lave den samme fejl to gange"],"a":"at klare to ting på én gang","r":"Man får to ting gjort med én handling, for eksempel at købe ind på vej hjem fra træning."},
{"l":1069,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvis man siger, at en person har 'lange fingre', hvad mener man så?","o":["at personen spiller klaver","at personen stjæler","at personen er meget høj","at personen skriver pænt"],"a":"at personen stjæler","r":"Lange fingre er et billede på en, der tager ting, som man ikke må tage."},
{"l":1089,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Viola tabte brætspillet for tredje gang. Hun sagde, at det var lige meget. Men hun stillede straks brikkerne op igen og sagde: En gang til!' Hvad ville Viola allerhelst?","o":["Holde op med at spille","Lære et nyt spil","Vinde bare én gang","Have hjælp til spillet"],"a":"Vinde bare én gang","r":"Hun siger, at det er lige meget, men hun vil spille igen med det samme. Det gør man, når man gerne vil vinde."},
{"l":1107,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler i ordsproget: 'Morgenstund har guld i ___.'","o":["hund","hånd","lomme","mund"],"a":"mund","r":"Stund og mund rimer. Ordsproget betyder, at det er godt at stå tidligt op."},
{"l":1129,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken forstavelse kan man sætte foran 'ærlig', så ordet får den modsatte betydning?","o":["u-","be-","for-","gen-"],"a":"u-","r":"Uærlig betyder ikke ærlig. Forstavelsen u- vender betydningen om, som i 'uvenlig' og 'utryg'."},
{"l":1149,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sara rullede sin sovepose sammen igen. Hun tjekkede lommelygten for tredje gang og satte vækkeuret to gange. I morgen skulle klassen sove i telt for første gang.' Hvorfor tjekker Sara alting flere gange?","o":["Hun er doven","Hun er spændt og lidt nervøs","Hun har mistet sin lommelygte","Hun har ikke lyst til at tage med"],"a":"Hun er spændt og lidt nervøs","r":"Når man tjekker tingene flere gange, er det tit, fordi man er spændt. Hun skal prøve noget for første gang."},
{"l":1167,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassen havde lavet en stor model af solsystemet. Pludselig slap en af snorene, og Jupiter trillede hen over gulvet. Alle sprang efter den, mens Amir holdt Saturn fast.' Hvad er 'Jupiter' i denne tekst?","o":["En elev i klassen","En bold fra idræt","En del af modellen","En af lærerne"],"a":"En del af modellen","r":"Jupiter hænger i en snor i modellen af solsystemet. Når snoren slipper, triller den."},
{"l":1189,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den røde sommerfrugt med små prikker på. Hvilken stavemåde er rigtig?","o":["jorbær","jordbar","jord bær","jordbær"],"a":"jordbær","r":"Ordet består af 'jord' og 'bær'. Det stumme d skal med, og det skrives i ét ord."},
{"l":1210,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I morges var søen spejlblank. Der var ikke en krusning, og man kunne se skyerne i vandet.' Hvad betyder 'spejlblank'?","o":["Helt stille og glat","Meget kold","Dyb og mørk","Fuld af fisk"],"a":"Helt stille og glat","r":"Vandet er uden krusninger, så skyerne spejler sig. Det er stille og glat som et spejl."},
{"l":1228,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er navneform af udsagnsordet i sætningen: 'Malik fandt en mønt på stranden.'","o":["finder","finde","fundet","fandt"],"a":"finde","r":"Navneformen står efter 'at'. 'Fandt' er datid, og navneformen er 'at finde'."},
{"l":1247,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Frugten er smal foroven og bred forneden. Find den rigtige stavemåde.","o":["pærre","pere","pære","pæræ"],"a":"pære","r":"Ordet skrives med æ og ét r. Vokalen er lang."},
{"l":1267,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af tillægsordet passer: 'Vi har fået et ___ køkken.'","o":["ny","nye","nyest","nyt"],"a":"nyt","r":"Det hedder et køkken, så tillægsordet skal have -t: et nyt køkken."},
{"l":1288,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jens fandt en gammel tegning bag i skuffen. På den stod der med skæve bogstaver: Til far. Hans far tog den, smilede og fik våde øjne.' Hvorfor fik far våde øjne?","o":["Han blev rørt over den gamle tegning","Han fik støv i øjnene","Han var ked af, at tegningen lå i skuffen","Han kunne ikke læse de skæve bogstaver"],"a":"Han blev rørt over den gamle tegning","r":"De skæve bogstaver viser, at Jens tegnede den, da han var lille. Far smiler, så det er ikke, fordi han er ked af det. Han bliver rørt."},
{"l":1308,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal det første komma stå: 'Jeg har pakket madkasse drikkedunk jakke og hue.'?","o":["drikkedunk","madkasse","jakke","hue"],"a":"madkasse","r":"Opremsningen begynder med 'madkasse', og kommaet står mellem den første og den anden ting."},
{"l":1331,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klara ville gerne sige noget, men ordene satte sig fast. Hele klassen kiggede. Hun fik kun hvisket et par ord, før hun satte sig igen.' Hvorfor var det svært for Klara at tale?","o":["Hun havde ondt i halsen","Læreren sagde, hun skulle tie","Hun var flov og nervøs","Hun vidste ikke, hvad hun ville sige"],"a":"Hun var flov og nervøs","r":"Alle kigger på hende, og ordene sætter sig fast. Det sker, når man er nervøs. Der står, at hun gerne ville sige noget."},
{"l":1347,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form passer: 'En elefant er ___ end en hund.'","o":["støre","størere","storre","større"],"a":"større","r":"Ordet kommer af 'stor', men skrives med ø og to r'er."},
{"l":1369,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Butikken lovede 'guld og grønne skove', men kunderne fik næsten ingenting. Hvad gjorde butikken?","o":["Den lovede mere, end den kunne holde","Den lovede at plante træer i haven","Den lovede at passe godt på naturen","Den lovede at give alle en gave"],"a":"Den lovede mere, end den kunne holde","r":"Guld og grønne skove er store ting, som ingen bare kan give. Derfor er løftet for stort til at holde."},
{"l":1389,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Tallet, der skrives 100. Hvilket ord er stavet rigtigt?","o":["hundrade","hundrede","hunderede","hunnrede"],"a":"hundrede","r":"Ordet skrives med nd og slutter på -rede, så der er to d'er. Det første d er stumt."},
{"l":1407,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kan du regne med, hvis din ven er 'pålidelig'?","o":["at vennen altid kommer for sent","at vennen tit glemmer aftaler","at vennen holder det, der er lovet","at vennen ikke kan lide at lege"],"a":"at vennen holder det, der er lovet","r":"En pålidelig ven kan man stole på, for det, I har aftalt, bliver gjort."},
{"l":1429,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer: 'Der ligger en hat på bordet. ___ er rød.'","o":["Hat","Hatte","Hattene","Hatten"],"a":"Hatten","r":"Vi ved, hvilken hat det er, så ordet står i bestemt form. Efter kort vokal fordobles t: hatten."},
{"l":1445,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal afslutte sætningen, når Mikkel skriver til sin bror: 'Må jeg låne din cykel'?","o":["spørgsmålstegn","punktum","komma","udråbstegn"],"a":"spørgsmålstegn","r":"Mikkel beder om lov og venter på et svar. Sætningen begynder med udsagnsordet 'må' og er et spørgsmål."},
{"l":1467,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det var sidste kamp i sæsonen. Holdet havde tabt alle de andre, men i dag førte de med ét mål. Da dommeren fløjtede af, kastede spillerne sig om halsen på hinanden.' Hvorfor blev spillerne så glade?","o":["Sæsonen var endelig slut","Det var deres første sejr","De havde scoret mange mål","De havde fået en ny dommer"],"a":"Det var deres første sejr","r":"De havde tabt alle andre kampe, så denne sejr var den første. Det gør den ekstra stor."},
{"l":1489,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt ordet i flertal: 'I ferien sov vi tre ___ i telt.'","o":["nat","natten","nætter","nætterne"],"a":"nætter","r":"I flertal skifter a til æ, og t fordobles: en nat, tre nætter."},
{"l":1506,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'vild', når vi taler om dyr?","o":["stor","sulten","farlig","tam"],"a":"tam","r":"Et tamt dyr er vant til mennesker, mens et vildt dyr lever frit i naturen."},
{"l":1528,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et stort havdyr med lange hugtænder. Hvordan staves det?","o":["hvalros","valros","hvallros","hvalrås"],"a":"hvalros","r":"Ordet begynder med hv som 'hval'. Der er ét l, og det slutter på -ros."},
{"l":1548,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rasmus var sikker på, at han kunne hoppe over vandpytten. Han tog tilløb, sprang og landede med et plask lige i midten. Hans søster kunne ikke holde latteren tilbage.' Hvad gik der galt?","o":["Vandpytten var dybere, end han troede","Han sprang ikke langt nok","Han tog ikke tilløb først","Hans søster skubbede ham"],"a":"Han sprang ikke langt nok","r":"Han landede midt i vandpytten, så springet var for kort. Tilløb tog han, og hans søster grinede bare."},
{"l":1566,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Blæksprutten har en smart måde at slippe væk på. Når en fjende kommer for tæt på, sprøjter den en sky af blæk ud i vandet. Mens fjenden ikke kan se noget, svømmer den væk.' Hvad bruger blæksprutten blækket til?","o":["At fange sit bytte med","At farve vandet smukt","At skjule sig fra en fjende","At finde vej i mørket"],"a":"At skjule sig fra en fjende","r":"Blækskyen gør, at fjenden ikke kan se noget, og så kan blæksprutten slippe væk."},
{"l":1585,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Der var et hul i sokken. ___ blev større og større.'","o":["Hul","Huller","Hullerne","Hullet"],"a":"Hullet","r":"Vi ved, hvilket hul det er, så det er bestemt form. Et-ord får -et, og l fordobles: hullet."},
{"l":1609,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord står i navneform: 'Vi prøver at bygge en hule.'","o":["bygge","prøver","hule","Vi"],"a":"bygge","r":"Navneform står efter 'at'. 'Prøver' er et udsagnsord i nutid."},
{"l":1627,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'få øje på' noget?","o":["at have noget i sit ene øje","at opdage noget med øjnene","at lukke øjnene et kort øjeblik","at lede efter noget i lang tid"],"a":"at opdage noget med øjnene","r":"Når du får øje på noget, ser du det lige pludselig. Vendingen handler ikke om noget, der sidder i øjet."},
{"l":1647,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Yusuf havde glædet sig hele vinteren til at kælke på bakken. Men da de kom frem, var sneen smeltet. Han stod længe og kiggede på det grønne græs, før han fandt en bold frem i stedet.' Hvordan klarer Yusuf sin skuffelse?","o":["Han bliver sur og går hjem","Han beder om at køre videre","Han finder på noget andet at lave","Han venter på, at det sner igen"],"a":"Han finder på noget andet at lave","r":"Han kigger skuffet på græsset, men finder bolden frem. Han gør det bedste ud af situationen."},
{"l":1669,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige ord: 'Læreren ___ mig om lektierne i går.'","o":["spørger","spørge","spurgt","spurgte"],"a":"spurgte","r":"Det skete i går, så det skal være datid. 'At spørge' hedder 'spurgte' i datid."},
{"l":1688,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører sammen med tillægsordet 'glad'?","o":["glæde","glas","glans","gade"],"a":"glæde","r":"Den, der er glad, føler glæde. De andre ord ligner, men kommer ikke af 'glad'."},
{"l":1708,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Det var en ___ fejl, vi lavede i kampen.'","o":["ergerlig","ærgerlig","ærgelig","ærgerli"],"a":"ærgerlig","r":"Ordet begynder med æ og kommer af 'ærgre'. Det ender på -lig."},
{"l":1728,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassen skulle stemme om, hvor turen skulle gå hen. Fjorten ville i zoo, seks ville i skoven, og to ville på museum. Men zoo holdt lukket den dag, så klassen valgte det, der havde fået næstflest stemmer.' Hvor skal klassen hen?","o":["I zoologisk have","På museum","I skoven","På stranden"],"a":"I skoven","r":"Flest ville i zoo, men zoo holdt lukket. Næstflest stemmer fik skoven med seks stemmer."},
{"l":1746,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'vanskelig'?","o":["fin","klar","sjælden","svær"],"a":"svær","r":"En vanskelig opgave er en svær opgave, som kræver noget af dig."},
{"l":1765,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'Hver Fredag går Theo til svømning i Kolding.'?","o":["Fredag","Hver","Theo","Kolding"],"a":"Fredag","r":"Ugedage skrives med lille, når de ikke står først. 'Hver' står først, og Theo og Kolding er navne."},
{"l":1789,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer efter 'kan': 'Min hund kan ___ over søen.'","o":["svømmer","svømme","svømmede","svømmet"],"a":"svømme","r":"Efter 'kan' står navneform: svømme. Du kan prøve med 'at' foran for at høre det."},
{"l":1806,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'rovdyr'?","o":["et dyr, der kun lever af græs og blade","et dyr, der bor på en bondegård","et dyr, der fanger og spiser andre dyr","et dyr, der sover hele vinteren"],"a":"et dyr, der fanger og spiser andre dyr","r":"Rovdyr jager for at få føde. Ulve og ræve er rovdyr, mens køer spiser planter."},
{"l":1827,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Pigerne på holdet havde fundet på en hemmelig hilsen. De slog knoerne sammen og rørte ved albuen. Nora, som var ny, kiggede på og gjorde det langsomt efter.' Hvad vil Nora nok?","o":["Vise, at hilsnen er dum","Finde ud af, hvem der har fundet på den","Lære de andre en ny hilsen","Være med i hilsnen ligesom de andre"],"a":"Være med i hilsnen ligesom de andre","r":"Hun gør hilsnen efter, fordi hun er ny og gerne vil kunne den ligesom de andre."},
{"l":1849,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken grad står 'hurtigere' i?","o":["højere grad","højeste grad","grundform","flertal"],"a":"højere grad","r":"Rækken er hurtig, hurtigere, hurtigst. Højere grad bruges, når man sammenligner to."},
{"l":1866,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Katten ___ af velbehag, mens den lå på mit skød.'","o":["galede","spandt","vrinskede","kvækkede"],"a":"spandt","r":"Katte spinder, når de har det rart, og 'spandt' er datid af 'spinde'. Hanen galer, hesten vrinsker, og frøen kvækker."},
{"l":1889,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'holde af' nogen?","o":["at holde sig væk fra nogen","at holde fast i nogens jakke","at synes rigtig godt om nogen","at hilse på nogen om morgenen"],"a":"at synes rigtig godt om nogen","r":"Vi holder af dem, vi er glade for. Det har intet at gøre med at holde noget med hænderne."},
{"l":1908,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver gang Marius skulle læse højt, fik han ondt i maven. Så fandt læreren på, at han kunne øve sig for bibliotekets hund. Hunden grinede aldrig, og efter en måned læste Marius højt uden at tænke over det.' Hvorfor virkede det at læse for hunden?","o":["Hunden kunne hjælpe ham med ordene","Marius kan bedre lide hunde end mennesker","Biblioteket var mere stille end klassen","Hunden grinede ikke, så han blev tryg"],"a":"Hunden grinede ikke, så han blev tryg","r":"Han var bange for, hvad andre ville tænke. Hunden grinede aldrig, så han kunne øve sig i ro, til han blev modig."},
{"l":1926,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er der sket, hvis du har 'forsovet' dig?","o":["Du har sovet for længe.","Du har sovet for lidt.","Du har sovet på sofaen.","Du har sovet hos en ven."],"a":"Du har sovet for længe.","r":"Forstavelsen for- kan betyde, at noget går galt. Her har man sovet så længe, at man kommer for sent."},
{"l":1946,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Jeg vil gerne ___, hvad der sker i bogen.'","o":["hvide","vide","viide","vidæ"],"a":"vide","r":"Ordet betyder 'kende til' og skrives uden h. 'Hvide' er en farve. Der er blødt d i midten."},
{"l":1968,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kolibrien er en lille fugl, der kan stå stille i luften foran en blomst. Dens vinger slår så hurtigt, at man næsten ikke kan se dem. Den kan også flyve baglæns.' Hvad gør kolibrien særlig?","o":["At den kun kan flyve baglæns","At dens vinger står helt stille","At den kan stå stille i luften","At den er en stor fugl"],"a":"At den kan stå stille i luften","r":"Teksten fremhæver, at den kan stå stille i luften og flyve baglæns. Det kan de fleste fugle ikke."},
{"l":1986,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'sand', når vi taler om en historie?","o":["kort","spændende","gammel","opdigtet"],"a":"opdigtet","r":"En sand historie er virkelig sket. En opdigtet historie har nogen fundet på."},
{"l":2005,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige stedord: 'Hvor er ___ viskelæder?'","o":["mit","min","mine","mig"],"a":"mit","r":"Det hedder et viskelæder. Foran et-ord hedder det 'mit'."},
{"l":2025,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning fra indkøbslisten har kommaerne rigtigt?","o":["Husk mel, sukker, æg, og gær.","Husk mel, sukker, æg og gær.","Husk mel sukker æg, og gær.","Husk, mel sukker æg og gær."],"a":"Husk mel, sukker, æg og gær.","r":"Hver vare skilles fra den næste med komma, undtagen foran 'og'. Dér skal kommaet væk."},
{"l":2047,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'nøjagtig'?","o":["hurtig","pæn","præcis","ren"],"a":"præcis","r":"Noget nøjagtigt er helt præcist. For eksempel kan et ur vise den nøjagtige tid."},
{"l":2067,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Line og hendes far lavede en aftale: Hvis Line lavede lektier hver dag i en uge, måtte hun blive længe oppe på fredag. Torsdag aften lagde far blyanten foran hende med et smil.' Hvad vil far minde Line om?","o":["At hun skal i seng nu","At hun må blive længe oppe i aften","At han gerne vil lave lektier","At hun skal huske lektierne i aften"],"a":"At hun skal huske lektierne i aften","r":"Det er torsdag, og aftalen gælder hver dag i ugen. Blyanten minder Line om, at hun stadig skal lave lektier i aften."},
{"l":2085,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Når man er 'taknemmelig', hvad gør man så?","o":["Man sætter pris på det, man har fået.","Man vil gerne have mere af det hele.","Man synes, at man har for meget at lave.","Man bliver ked af en dårlig gave."],"a":"Man sætter pris på det, man har fået.","r":"Taknemmelighed er glæde over det, andre har givet eller gjort for en. Ordet hænger sammen med 'tak'."},
{"l":2107,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad måler man, når man tager sin 'puls'?","o":["hvor høj man er blevet","hvor hurtigt hjertet slår","hvor meget man vejer","hvor stærke ens arme er"],"a":"hvor hurtigt hjertet slår","r":"Pulsen er hjertets slag, som kan mærkes på håndleddet og på halsen. Den stiger, når man løber."},
{"l":2126,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Mor ___ på mig, da maden var klar.'","o":["kalte","kaldde","kaldte","kallte"],"a":"kaldte","r":"Datid af 'kalde' beholder d'et og får -te."},
{"l":2145,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Jeg ___ meget på dig i går.'","o":["tængte","tænkede","tenkte","tænkte"],"a":"tænkte","r":"Datid af 'tænke' ender på -kte og skrives med æ."},
{"l":2166,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Dorthe ville ikke indrømme, at hun var faret vild. Hun blev ved med at gå, som om hun vidste hvor, og sagde, at det var en genvej. Vi kom forbi den samme sten for tredje gang.' Hvad er det sjove i teksten?","o":["At Dorthe går rundt i ring","At Dorthe er god til at finde vej","At stenen flytter sig hele tiden","At Dorthe har tabt en sten"],"a":"At Dorthe går rundt i ring","r":"Forbi samme sten tre gange betyder, at de går i ring, selv om hun påstår, at det er en genvej."},
{"l":2185,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om slik og is har et komma, der ikke skal være der?","o":["Jeg kan lide is, kage og slik.","Jeg kan lide is, og kage.","Da jeg fik is, blev jeg glad.","Jeg købte is, slik og saft."],"a":"Jeg kan lide is, og kage.","r":"Når kun to ting er bundet sammen med 'og', skal der ikke komma imellem dem."},
{"l":2205,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Ved ___ trækker havet sig langt ud, og man kan gå på bunden.'","o":["flod","storm","ebbe","strøm"],"a":"ebbe","r":"Ebbe er, når vandet står lavt. Højvande kaldes flod, og sammen hedder det ebbe og flod, som man kender fra Vadehavet."},
{"l":2228,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at være 'misundelig'?","o":["at man gerne deler med andre","at man har glemt sine ting","at man er stolt af en ven","at man ønsker det, som andre har"],"a":"at man ønsker det, som andre har","r":"Den, der er misundelig, har det dårligt over, at andre har noget, man ikke selv har."},
{"l":2247,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Teksten på skiltet ved søen var kort: Tynd is. Alligevel gik Mathias tre skridt ud. Så hørte han et knæk under sig og stod helt stille.' Hvad må Mathias nu tænke?","o":["At skiltet havde ret","At han er sikker på isen","At han skal hente sine skøjter","At han skal gå længere ud"],"a":"At skiltet havde ret","r":"Han ignorerede skiltet, og nu knækker isen. Han indser, at advarslen var rigtig."},
{"l":2265,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvis man kaster en sten i vandet, ser man ringe brede sig. Sådan er det også med rygter, sagde læreren. Det, man siger til én, bliver hurtigt kendt af mange.' Hvad sammenligner læreren?","o":["Sten og mennesker","Ringe i vandet og rygter","Vand og sprog","Rygter og sandhed"],"a":"Ringe i vandet og rygter","r":"Rygter breder sig fra én til mange, sådan som ringene breder sig på vandet."},
{"l":2287,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'bedrøvet'?","o":["vred","træt","trist","sulten"],"a":"trist","r":"Den, der er bedrøvet, er ked af det. Det er et lidt finere ord for trist."},
{"l":2305,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken del af sætningen er ledsætningen: 'Når vi har fri, tager vi i svømmehallen.'?","o":["tager vi","i svømmehallen","vi i svømmehallen","Når vi har fri"],"a":"Når vi har fri","r":"'Når vi har fri' kan ikke stå alene som sætning. Ordet 'når' viser, at det er en ledsætning."},
{"l":2326,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Bilen, der kører syge mennesker til hospitalet. Hvilken stavemåde er rigtig?","o":["ambulance","ambulanse","ambolance","ampulance"],"a":"ambulance","r":"Ordet ender på -ance, ligesom 'balance'. C'et lyder som s."},
{"l":2346,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der var ikke meget at se i lejligheden efter flytningen. Kun Lauras seng stod samlet. Hun lå og kiggede op på en ny lampe, som mor havde hængt op, og lyttede til en by, hun ikke kendte endnu.' Hvordan føles det nye sted for Laura?","o":["Fyldt","Fremmed","Kendt","Trygt"],"a":"Fremmed","r":"Der er næsten tomt, og hun kender ikke byen. Det føles fremmed for hende."},
{"l":2365,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad mangler der, for at det bliver en sætning: 'Hele klassen til Skagen i maj'?","o":["grundleddet","navneordet","udsagnsleddet","forholdsordet"],"a":"udsagnsleddet","r":"Vi ved, hvem det handler om, men ikke hvad de gør. Der mangler et ord som 'rejser'."},
{"l":2385,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have komma efter sig: 'Før vi tager af sted skal vi pakke tasken.'?","o":["tager","skal","vi","sted"],"a":"sted","r":"Ledsætningen er 'Før vi tager af sted'. Den slutter efter 'sted', og hovedsætningen begynder med 'skal'."},
{"l":2406,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skildpadden lever meget længe. Nogle store skildpadder kan blive over hundrede år. Den bevæger sig langsomt og bruger ikke meget energi.' Hvad oplyser teksten om skildpadder?","o":["At de kan blive meget gamle","At alle skildpadder bliver over hundrede år","At de bevæger sig langsomt, fordi de er gamle","At de kun lever hundrede år"],"a":"At de kan blive meget gamle","r":"Teksten siger, at de lever længe. Men det er kun nogle store skildpadder, der bliver over hundrede år, og teksten siger ikke, at de er langsomme på grund af alderen."},
{"l":2425,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'maler' i sætningen: 'Naboen er maler og arbejder i Horsens.'","o":["udsagnsord","navneord","tillægsord","biord"],"a":"navneord","r":"Her er 'maler' et arbejde, og man kan sige 'en maler'. Så er det et navneord."},
{"l":2445,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vores klasse skal se nationalmuseet i København.'?","o":["klasse","skal","nationalmuseet","se"],"a":"nationalmuseet","r":"Nationalmuseet er navnet på et bestemt museum. Ordet 'museum' alene ville blive skrevet med lille."},
{"l":2468,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hvad hedder din hund ___?'","o":["egenlig","ejentlig","egentli","egentlig"],"a":"egentlig","r":"Ordet skrives med g og t foran -lig. Husk t'et, selvom det kan lyde som d."},
{"l":2485,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"I hvilken sætning er 'drømme' et udsagnsord?","o":["Jeg kan godt lide at drømme.","Mine drømme var sjove i nat.","Hun fortalte om sine drømme.","Gode drømme gør mig glad."],"a":"Jeg kan godt lide at drømme.","r":"Efter 'at' står udsagnsordet i navneform. I de andre sætninger er 'drømme' flertal af navneordet 'en drøm'."},
{"l":2505,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassens hamster hedder Einstein. Den kan finde ud af en labyrint, men kun hvis der ligger en gulerod for enden. Uden guleroden sætter den sig bare og vasker sine ører.' Hvad får Einstein til at løse labyrinten?","o":["Den er meget klog","Der er mad at hente","Den keder sig i buret","Den har lært det på skolen"],"a":"Der er mad at hente","r":"Den gør det kun, når guleroden ligger der. Det er altså maden, der får den i gang."},
{"l":2525,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Tvillingerne ser helt ___ ud.'","o":["forsgellige","forskelige","forskellige","forskællige"],"a":"forskellige","r":"Ordet skrives med sk, e og to l'er, og det slutter på -ige i flertal."},
{"l":2545,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Mens Ella læste lektier lavede Mads mad.'?","o":["læste","lavede","Mads","lektier"],"a":"lektier","r":"Ledsætningen 'Mens Ella læste lektier' slutter efter 'lektier'. Hovedsætningen begynder med 'lavede'."},
{"l":2565,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket tillægsord hører til navneordet 'mod'?","o":["modig","moden","moderne","modsat"],"a":"modig","r":"Den, der har mod, er modig. De andre ord ligner, men handler ikke om at turde noget."},
{"l":2586,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg tror ikke på spøgelser, sagde Benjamin. Han sagde det med høj stemme, mens han gik gennem kælderen og holdt lommelygten med begge hænder.' Hvad viser hans måde at tale og gå på?","o":["At han er modig og tryg i kælderen","At han nok er mere bange, end han siger","At han gerne vil finde et spøgelse","At lommelygten er meget tung at bære"],"a":"At han nok er mere bange, end han siger","r":"Han taler højt for at berolige sig selv og holder hårdt om lygten. Hans ord og hans krop passer ikke sammen."},
{"l":2605,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler kommaet: 'Selvom Hassan var træt ville han ikke i seng.'?","o":["var","ville","træt","han"],"a":"træt","r":"'Selvom Hassan var træt' er en ledsætning. Den står først, så kommaet skal stå lige efter den."},
{"l":2626,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at 'overtale' nogen?","o":["at tale højere end dem","at tale dårligt om dem","at tale med dem i telefon","at få dem til at sige ja"],"a":"at få dem til at sige ja","r":"Når man overtaler nogen, får man dem med gode grunde til at gøre noget, de først ikke ville."},
{"l":2649,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det store, kolde apparat i køkkenet, hvor mælk og ost står. Hvilket ord er stavet rigtigt?","o":["køleskab","kølleskab","køleskap","kølæskab"],"a":"køleskab","r":"Ordet består af 'køle' og 'skab'. Det ender på b."},
{"l":2665,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Kan du finde amazonas på kortet?'","o":["du","amazonas","finde","kortet"],"a":"amazonas","r":"Amazonas er navnet på en stor flod i Sydamerika. Geografiske navne skrives med stort."},
{"l":2686,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at træne 'regelmæssigt'?","o":["at træne efter alle reglerne","at træne så hårdt, man kan","at træne med faste mellemrum","at træne, når man lige har lyst"],"a":"at træne med faste mellemrum","r":"Noget regelmæssigt sker jævnligt, for eksempel hver tirsdag. Ordet handler om faste tider og ikke om regler i spillet."},
{"l":2706,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet, hvor du betaler for at få mad serveret. Hvilket ord er stavet rigtigt?","o":["restaurent","resturant","restorant","restaurant"],"a":"restaurant","r":"Ordet kommer fra fransk og skrives med au midt i. Det slutter på -ant."},
{"l":2725,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Vi sendte et kort til vores ven på færøerne.'?","o":["færøerne","sendte","kort","ven"],"a":"færøerne","r":"Færøerne er navnet på en øgruppe i Nordatlanten, så ordet skal have stort bogstav."},
{"l":2747,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sidste dag i sommerferien sad Emma på stranden og følte 'vemod'. Hvad følte hun?","o":["en vild glæde over noget helt nyt","en lille tristhed over, at noget er forbi","en stærk vrede over en uretfærdighed","en stor angst for at blive alene"],"a":"en lille tristhed over, at noget er forbi","r":"Ferien har været god, men nu er den slut. Så kan man blive lidt trist, selvom man også er glad for det, man har haft."},
{"l":2766,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det var ikke, fordi Ingeborg var dårlig til matematik. Hun troede bare, at hun var. Da en ny lærer viste hende, at hun havde regnet rigtigt tre gange, ændrede noget sig i hendes ansigt.' Hvad er det egentlige problem i teksten?","o":["At opgaverne er for svære","At hendes lærer er streng","At hun ikke tror på sig selv","At hun ikke kan tabellerne"],"a":"At hun ikke tror på sig selv","r":"Teksten siger, at hun ikke var dårlig, men kun troede det. Problemet er hendes selvtillid."},
{"l":2785,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at 'antyde' noget?","o":["at råbe det højt for alle","at sige det helt tydeligt","at skrive det ned på et papir","at sige det på en skjult måde"],"a":"at sige det på en skjult måde","r":"Den, der antyder, siger det ikke lige ud, men lader andre gætte det."},
{"l":2807,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at have 'rent mel i posen'?","o":["at man ikke har noget at skjule","at man er en dygtig bager","at man har gjort rent i køkkenet","at man er rig og har mange penge"],"a":"at man ikke har noget at skjule","r":"Vendingen betyder, at man er ærlig og ikke har gjort noget forkert."},
{"l":2829,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Kongens datter. Hvordan staves det?","o":["prinsese","prinsesse","prinssesse","prinsæsse"],"a":"prinsesse","r":"Ordet har ét s i midten og to s'er mod slutningen."},
{"l":2847,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange i klassen synes, at Malene er stille. Men de har aldrig set hende på scenen. Der er hun en, der fylder hele rummet med sin stemme.' Hvad vil teksten vise?","o":["At Malene ikke kan lide at stå på scenen","At Malene er den mest stille i klassen","At Malene er anderledes, end de andre tror","At Malene er blevet en kendt skuespiller"],"a":"At Malene er anderledes, end de andre tror","r":"Hun virker stille i klassen, men på scenen fylder hun hele rummet. De andre kender hende ikke helt."},
{"l":2867,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kan stå i stedet for 'straks' i sætningen: 'Hun svarede straks på beskeden.'","o":["lidt efter lidt","næste dag","en gang imellem","med det samme"],"a":"med det samme","r":"Straks betyder uden at vente. Hun lod altså ikke beskeden ligge, men svarede lige efter, hun havde læst den."},
{"l":2884,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om vinduet skal slutte med spørgsmålstegn?","o":["Er vinduet stadig lukket","Vinduet er stadig lukket","Hun spurgte, om vinduet var lukket","Jeg ved ikke, om vinduet er lukket"],"a":"Er vinduet stadig lukket","r":"Her står udsagnsordet 'er' før grundleddet 'vinduet', og sætningen spørger selv. De to med 'om' fortæller kun om et spørgsmål og får punktum."},
{"l":2905,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Find det ord, der mangler: 'Mia vil altid vide, hvad der gemmer sig i kasserne. Hun er meget ___.'","o":["træt","nysgerrig","genert","doven"],"a":"nysgerrig","r":"Den, der altid vil vide mere og undersøge tingene, er nysgerrig."},
{"l":2926,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt her? 'Far ___ suppen, mens vi dækker bord.'","o":["krydre","kryder","krydrer","krydder"],"a":"krydrer","r":"Navnemåden er 'krydre', så der står r både før og efter e. Det sker nu, så ordet skal have nutids-r."},
{"l":2943,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Malik pakkede sin taske langsomt. Han lagde bogen ned, tog den op og lagde den ned igen. Mor kaldte for tredje gang fra gangen. I dag skulle han begynde på den nye skole, hvor han ikke kendte en eneste.' Hvorfor er Malik så længe om at pakke?","o":["Han kan ikke finde sin bog","Han er ikke vågnet ordentligt endnu","Han venter på, at mor bliver færdig","Han er nervøs for den nye skole"],"a":"Han er nervøs for den nye skole","r":"Teksten slutter med, at han ikke kender nogen på den nye skole. Det forklarer, hvorfor han trækker tiden ud."},
{"l":2965,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'runesten'?","o":["en sten med gamle indhuggede tegn","en glat sten fra stranden til smykker","en sten, man sleb sværd og knive på","en stor sten, man byggede huse af"],"a":"en sten med gamle indhuggede tegn","r":"Vikingerne huggede runer, altså deres skrifttegn, i store sten. Tit var det for at mindes en person."},
{"l":2981,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse hører 'fordi' til i sætningen: 'Hun løb, fordi bussen var på vej.'","o":["forholdsord","bindeord","biord","stedord"],"a":"bindeord","r":"'Fordi' binder to sætninger sammen og fortæller årsagen. Det gør det til et bindeord."},
{"l":3003,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord passer: 'Du må selv ___, hvilken film vi skal se.'","o":["vælje","vælger","vælge","vællge"],"a":"vælge","r":"Efter 'må' står navnemåden. Ordet høres med j, men staves med lg."},
{"l":3025,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find ordenstallet: 'Noor bor på femte sal i en blok med otte etager.'","o":["otte","blok","etager","femte"],"a":"femte","r":"'Femte' fortæller om rækkefølgen og er et ordenstal. 'Otte' fortæller et antal og er et grundtal."},
{"l":3047,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om Ali og fiskene står i datid?","o":["Ali fangede tre fisk.","Ali fanger tre fisk.","Ali har fanget tre fisk.","Ali skal fange tre fisk."],"a":"Ali fangede tre fisk.","r":"'Fangede' er datid med kun ét udsagnsord. 'Har fanget' er førnutid, som består af to ord."},
{"l":3062,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer til en person, der mest tænker på sig selv?","o":["gavmild","egoistisk","beskeden","tålmodig"],"a":"egoistisk","r":"Ego betyder jeg på latin. Den, der er egoistisk, sætter sig selv først og tænker sjældent på andre."},
{"l":3085,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken af disse linjer ligner mest en overskrift i en avis?","o":["Kære forældre, skolen åbner efter ferien","Besøg vores nye skole, og tilmeld dig i dag","Ny skole åbner i Ribe efter sommerferien","I dag var min første dag på den nye skole"],"a":"Ny skole åbner i Ribe efter sommerferien","r":"En avisoverskrift siger kort, hvad der er sket eller skal ske, og hvor. De andre linjer hører til brev, reklame og dagbog."},
{"l":3102,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Tøjet skal ___ pænt sammen.'","o":["ligges","lægger","læges","lægges"],"a":"lægges","r":"Nogen skal flytte på tøjet, så ordet kommer af 'lægge'. Efter 'skal' står der her en form på -s."},
{"l":3124,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Stop legen, og ___ så bolden fra dig!'","o":["læg","lig","lagde","ligg"],"a":"læg","r":"Det er en opfordring til at flytte bolden, så ordet er 'lægge'. Bydeformen af 'lægge' hedder 'læg'."},
{"l":3146,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Bedstefar sov ___ i sin lænestol.'","o":["siddene","siddende","sidende","sættende"],"a":"siddende","r":"Ordet kommer af 'sidde' med dobbelt d. Lang tillægsform ender på -ende."},
{"l":3167,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad hedder det? 'Bier flytter pollen fra blomst til blomst, så der kan komme frø. Det kaldes ___.'","o":["vanding","gødskning","bestøvning","fordøjelse"],"a":"bestøvning","r":"Pollen er blomsternes støv. Når det kommer over på en anden blomst, er blomsten bestøvet."},
{"l":3185,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvorfor lykkes det Gerda at få Kay med hjem i 'Snedronningen'?","o":["Hun kæmper med et sværd mod Snedronningen","Hun narrer Snedronningen med en gylden ring","Hun betaler røverne for at hente ham hjem","Hendes tårer smelter isen i hans hjerte"],"a":"Hendes tårer smelter isen i hans hjerte","r":"Gerda vinder ikke med magt, men med kærlighed. Hendes varme tårer tør isklumpen i Kays hjerte op."},
{"l":3205,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Da Lukas så hunden, 'vendte han på en tallerken' og løb hjem. Hvad gjorde han?","o":["Han vendte lynhurtigt om","Han satte sig ned for at spise","Han tabte sin mad på gulvet","Han gik langsomt videre ad vejen"],"a":"Han vendte lynhurtigt om","r":"En tallerken er lille, så den, der vender på en tallerken, drejer rundt lynhurtigt og på meget lidt plads."},
{"l":3223,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg rigtigt: 'Nu går I for ___ med jeres sjov, sagde læreren.'","o":["hvidt","vidt","vit","vidst"],"a":"vidt","r":"I vendingen betyder ordet 'langt', og det har intet med farven at gøre. Derfor er der ikke noget h."},
{"l":3245,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hun har stor ___ om dinosaurer.'","o":["videnn","hviden","viden","vidden"],"a":"viden","r":"Ordet hænger sammen med 'at vide', så der er ikke noget h. Der er ét d og ét n."},
{"l":3264,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn passer på den tomme plads: '»Hvem har læst bogen___« spurgte læreren.'?","o":["punktum","kolon","komma","spørgsmålstegn"],"a":"spørgsmålstegn","r":"Læreren stiller et spørgsmål, så tegnet skal være spørgsmålstegn, også selv om 'spurgte læreren' kommer bagefter. Det står inde i anførselstegnene, fordi det hører til lærerens ord."},
{"l":3283,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i titlen skal skrives med stort: 'Vi læser »den grimme ælling« i dansk.'?","o":["den","grimme","ælling","dansk"],"a":"den","r":"I en titel får det første ord stort bogstav. Her skrives de andre ord i titlen med lille."},
{"l":3300,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg det rigtige ord: 'Hun ___ bogen på hylden, inden hun gik.'","o":["lå","lagde","ligger","lagt"],"a":"lagde","r":"Her flytter hun noget, nemlig bogen. Så er det 'at lægge', og datid hedder 'lagde'."},
{"l":3322,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Hun er den bedste ___ på holdet.'","o":["spillere","spillerer","spiller","spilder"],"a":"spiller","r":"Der er tale om én person, så navneordet står i ental. Dobbelt l, fordi i'et er kort."}
